def maxArea(height):
    l, r, best = 0, len(height) - 1, 0
    while l < r:
        area = min(height[l], height[r]) * (r - l)  # 短板决定水位
        best = max(best, area)
        if height[l] < height[r]:                   # 移动短板侧
            l += 1
        else:
            r -= 1
    return best

