def merge(nums1, m, nums2, n):
    i, j, k = m - 1, n - 1, m + n - 1
    while j >= 0:                       # nums2 用完即结束
        if i >= 0 and nums1[i] > nums2[j]:
            nums1[k] = nums1[i]         # 取较大者放尾部
            i -= 1
        else:
            nums1[k] = nums2[j]
            j -= 1
        k -= 1
